import {setupMicrophone} from './microphone.js';
import {DictationSession,insertionForSpeech,speechErrorMessage} from './dictation-core.js';
const mic='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="9" y="3" width="6" height="12" rx="3"/><path d="M6 10v2a6 6 0 0 0 12 0v-2M12 18v3m-3 0h6"/></svg>';
const stop='<svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><rect x="7" y="7" width="10" height="10" rx="2"/></svg>';
const draftKey='gun-payi-voice';
export function voiceButton(selector,label='Türkçe sesle yaz',className='voice-button'){return `<button type="button" class="${className}" data-voice-target="${selector}" aria-label="${label}" aria-pressed="false" title="Türkçe sesle yaz · Ses tarayıcının tanıma hizmetinde işlenebilir">${mic}<span>Sesle yaz</span></button>`}
export function setupVoice({notify=()=>{},onRecover=()=>{}}={}){
 let session=null,selector='',original='',start=0,end=0,status=null,writing=false,suppress=false,lastText='',waiters=[],hideTimer,hiddenTimer;
 const permissions=setupMicrophone({onChange:()=>{const el=document.querySelector('#microphone-permission');if(el)el.textContent=permissionLabel();}});
 const permissionLabel=()=>({granted:'Mikrofon izni: açık. Kalıcı tutulması tarayıcının ayarına bağlıdır.',denied:'Mikrofon izni: kapalı. Site izinlerinden açabilirsin.',prompt:'Mikrofon izni: sorulacak.',unknown:'Mikrofon iznini bu tarayıcı yönetiyor.'}[permissions.state()]);
 void permissions.refresh();
 const engine=()=>window.SpeechRecognition||window.webkitSpeechRecognition;
 const flush=()=>{for(const resolve of waiters.splice(0))resolve()};
 function buttons(recording=false){for(const b of document.querySelectorAll('[data-voice-target]')){const match=b.dataset.voiceTarget===selector&&recording;b.classList.toggle('recording',match);b.setAttribute('aria-pressed',String(match));b.setAttribute('aria-label',match?'Türkçe dikteyi durdur':(b.dataset.voiceTarget.includes('note')?'Notu Türkçe sesle yaz':'Türkçe sesle yaz'));b.innerHTML=(match?stop:mic)+'<span>'+(match?'Durdur':'Sesle yaz')+'</span>';}}
 function statusFor(target){clearTimeout(hideTimer);document.querySelectorAll('.dictation-status').forEach(n=>n.remove());const el=document.createElement('div');el.className='dictation-status';el.setAttribute('role','status');el.setAttribute('aria-live','polite');const anchor=target.closest('.quick-entry')||target.closest('label')||target;anchor.after(el);status=el;return el;}
 function show(message,isError=false,keep=false){if(!status?.isConnected)return;status.textContent=message;status.classList.toggle('error',isError);if(!keep){clearTimeout(hideTimer);hideTimer=setTimeout(()=>status?.remove(),isError?9000:2500);}}
 function saveOverflow(text){try{localStorage.setItem(draftKey,JSON.stringify({text,at:Date.now()}))}catch{}if(status?.isConnected){status.textContent='Başlık uzadı. Metnin korunuyor. ';const b=document.createElement('button');b.type='button';b.textContent='Not olarak aç';b.className='inline-link';b.addEventListener('click',()=>{onRecover(text);try{localStorage.removeItem(draftKey)}catch{}});status.append(b);}}
 function apply(s){if(suppress)return;const target=document.querySelector(selector);if(!target){close();return;}if(s.capturing&&document.hidden){clearTimeout(hiddenTimer);hiddenTimer=setTimeout(()=>{if(document.hidden)close()},500);}const active=['starting','listening','stopping'].includes(s.phase);buttons(active&&s.capturing===true);for(const b of document.querySelectorAll('[data-voice-target]'))if(b.dataset.voiceTarget===selector){b.dataset.voiceState=s.phase;b.setAttribute('aria-busy',String(s.phase==='starting'||s.phase==='listening'&&!s.capturing));}for(const b of document.querySelectorAll('[data-action=quick-capture]'))b.classList.toggle('recording',active&&s.capturing===true&&selector==='#quick-title');
  if(s.preview&&s.preview!==lastText){const opts={current:original,original,start,end,spoken:s.preview,multiline:target.tagName==='TEXTAREA',maxLength:target.maxLength>=0?target.maxLength:Infinity},next=insertionForSpeech(opts);if(!next.ok&&next.reason==='length'){const full=insertionForSpeech({...opts,maxLength:Infinity});suppress=true;session?.dispose();suppress=false;session=null;buttons(false);flush();saveOverflow(full.value||s.preview);return;}if(next.ok){writing=true;target.value=next.value;target.dispatchEvent(new Event('input',{bubbles:true}));writing=false;lastText=s.preview;}}
  if(s.phase==='starting')show('Mikrofon hazırlanıyor…',false,true);else if(s.phase==='listening')show(s.capturing?'Türkçe dinleniyor… Bitirmek için mikrofona tekrar dokun.':'Mikrofon açılıyor… İzin penceresini kontrol et.',false,true);else if(s.phase==='stopping')show('Son sözlerin tamamlanıyor…',false,true);else{flush();if(s.error)show(speechErrorMessage(s.error),true);else show(s.preview?'Dikte tamamlandı.':'Konuşma algılanmadı.');}
 }
 function close(){clearTimeout(hiddenTimer);const previous=session;session=null;if(previous){previous.suspend();previous.dispose();}buttons(false);flush();}
 function toggleFor(nextSelector){if(session?.active&&selector===nextSelector)session.stop();else startFor(nextSelector);}
 function startFor(nextSelector){close();const target=document.querySelector(nextSelector);if(!target||target.disabled)return;selector=nextSelector;original=target.value;start=target.selectionStart;end=target.selectionEnd;lastText='';statusFor(target);if(!engine()){show(speechErrorMessage('unsupported'),true);return;}session=new DictationSession({createRecognition:()=>new (engine())(),onChange:apply});session.start();}
 async function finishFor(form){if(!session?.active||!selector)return;const target=document.querySelector(selector);if(!target||!form.contains(target))return;const pending=new Promise(resolve=>waiters.push(resolve));session.stop();await pending;}
 document.addEventListener('click',async e=>{const b=e.target.closest('button,input[type=submit]'),form=b?.form,target=selector?document.querySelector(selector):null;if(b?.type!=='submit'||!form||!session?.active||!target||!form.contains(target))return;e.preventDefault();e.stopImmediatePropagation();b.disabled=true;try{await finishFor(form);b.disabled=false;if(form.isConnected)form.requestSubmit();}finally{b.disabled=false;}},true);
 document.addEventListener('click',e=>{const b=e.target.closest('[data-voice-target]');if(!b)return;e.preventDefault();if(session?.active&&b.dataset.voiceTarget===selector)session.stop();else startFor(b.dataset.voiceTarget)});
 document.addEventListener('input',e=>{if(!writing&&session&&e.target.matches(selector)){suppress=true;session.dispose();session=null;suppress=false;buttons(false);flush();show('Dikte durdu; düzenlemeye devam edebilirsin.');}});
 document.addEventListener('keydown',e=>{if(e.key==='Escape'&&session?.active){e.preventDefault();e.stopImmediatePropagation();close();}},true);
 document.addEventListener('visibilitychange',()=>{clearTimeout(hiddenTimer);if(document.hidden){if(session?.state.phase==='starting')hiddenTimer=setTimeout(()=>{if(document.hidden)close()},45000);else close();}else void permissions.refresh();});window.addEventListener('pagehide',close);
 return {close,startFor,toggleFor,permissionLabel,authorize:()=>permissions.authorize(),isOpen:()=>Boolean(session?.active),beforeRender:close,finishFor,clearDraft:()=>{try{localStorage.removeItem(draftKey)}catch{}},recoverDraft:()=>{try{const d=JSON.parse(localStorage.getItem(draftKey));if(d?.text){onRecover(d.text);localStorage.removeItem(draftKey)}}catch{}}};
}
